cases.query:
PREFIX foaf: <http://xmlns.com/foaf/0.1/> 
PREFIX site: <http://example.org/stats#> 
CONSTRUCT { 
  ?iri foaf:name ?name . 
  ?iri foaf:nick ?nick . 
} 
WHERE { 
  ?iri foaf:name ?name ; 
    site:hits ?hits ; 
    foaf:nick ?nick . 
} 
ORDER BY desc(?hits) 
LIMIT 3

PREFIX dcat: <http://www.w3.org/ns/dcat#>

